style.css:
@-moz-document domain("classroom.google.com") {
:root {
    --melody-pink: #ffd6e8;
    --melody-dark-pink: #ffb6c1;
    --melody-white: #fffafa;
    --melody-accent: #f9a0c3;
    --melody-text: #5a4a4a;
  }

  /* General Page */
  body, .YVvGBb, .U26fgb, .tL9Q4c {
    background-color: var(--melody-pink) !important;
    color: var(--melody-text) !important;
    font-family: "Poppins", "Comic Sans MS", cursive !important;
  }

  /* Class cards on homepage */
  .JAPqpe, .onkcGd {
    background-color: var(--melody-white) !important;
    border: 2px solid var(--melody-dark-pink) !important;
    border-radius: 14px !important;
    box-shadow: 0 4px 10px rgba(255, 182, 193, 0.3) !important;
  }

  .onkcGd:hover {
    box-shadow: 0 6px 12px rgba(249, 160, 195, 0.5) !important;
    transform: translateY(-2px);
    transition: all 0.3s ease;
  }

  /* Headers / Navigation bar */
  header, .qhnNic, .G6Epef {
    background-color: var(--melody-dark-pink) !important;
    color: white !important;
  }

  /* Buttons */
  .U26fgb, .RveJvd, .nCP5yc, .pQGxvd {
    background-color: var(--melody-accent) !important;
    color: white !important;
    border-radius: 10px !important;
    transition: 0.3s ease !important;
  }

  .U26fgb:hover, .RveJvd:hover {
    background-color: var(--melody-dark-pink) !important;
    box-shadow: 0 0 10px var(--melody-accent) !important;
  }

  /* Assignments and classwork area */
  .VfPpkd-ksKsZd-XxIAqe, .z3vRcc, .O3Dpxe {
    background-color: var(--melody-white) !important;
    border-radius: 12px !important;
  }

  /* Text links */
  a {
    color: var(--melody-accent) !important;
    text-decoration: none !important;
  }
  a:hover {
    text-decoration: underline wavy var(--melody-dark-pink) !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: var(--melody-white);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--melody-dark-pink);
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--melody-accent);
  }

  /* Selection */
  ::selection {
    background: var(--melody-accent);
    color: var(--melody-white);
  }

  /* Cute rounded corners for everything */
  * {
    border-radius: 6px !important;
  }
}
